-- Correct completions across all three learning activities. Existing account/session
-- authentication is intentionally reused; no student rows are readable anonymously.
create table public.special_learning_catalog (
 course_id uuid not null references public.special_flash_courses(id) on delete cascade,
 kind text not null check(kind in ('blank','polysemy')),
 exercise text not null,
 answers jsonb not null,
 primary key(kind,exercise)
);
create index special_learning_catalog_course_idx on public.special_learning_catalog(course_id);
create table public.special_learning_events (
 account_id uuid not null references public.special_flash_accounts(id) on delete cascade,
 course_id uuid not null references public.special_flash_courses(id) on delete cascade,
 event_key text not null,
 kind text not null check(kind in ('card','blank','polysemy')),
 points integer not null default 0 check(points>=0),
 duration_ms bigint not null default 0 check(duration_ms>=0),
 occurred_at timestamptz not null default now(),
 primary key(account_id,event_key)
);
create index special_learning_events_course_date_idx on public.special_learning_events(course_id,occurred_at,account_id);
create table public.special_learning_state (
 account_id uuid not null references public.special_flash_accounts(id) on delete cascade,
 key text not null check(length(key)<=200),
 value jsonb not null,
 updated_at timestamptz not null default now(),
 primary key(account_id,key)
);
alter table public.special_learning_catalog enable row level security;
alter table public.special_learning_events enable row level security;
alter table public.special_learning_state enable row level security;
revoke all on public.special_learning_catalog,public.special_learning_events,public.special_learning_state from public,anon,authenticated;

-- Freeze legacy history once. New per-question events must never be added to
-- completed-round totals again. Only known/correct cards contribute points.
insert into public.special_learning_events(account_id,course_id,event_key,kind,points,duration_ms,occurred_at)
select a.account_id,d.course_id,'legacy-attempt:'||a.id,'card',least(a.cards,a.known),a.duration_ms,a.ended_at
from public.special_flash_attempts a join public.special_flash_decks d on d.id=a.deck_id;
insert into public.special_learning_events(account_id,course_id,event_key,kind,points,occurred_at)
select p.account_id,d.course_id,'legacy-marks:'||p.deck_id,'card',greatest(0,
 (select count(*) from jsonb_each_text(p.marks) m where m.value='green')-
 coalesce((select sum(least(a.cards,a.known)) from public.special_flash_attempts a where a.account_id=p.account_id and a.deck_id=p.deck_id),0)),p.updated_at
from public.special_flash_progress p join public.special_flash_decks d on d.id=p.deck_id;

create function public._special_learning_course(p_account uuid,p_kind text,p_exercise text)
returns uuid language plpgsql stable set search_path='' as $$
declare c uuid;
begin
 if p_kind='card' then
  if not public._special_flash_access(p_account,p_exercise::uuid) then raise exception 'Exercise is not available.' using errcode='42501';end if;
  select course_id into c from public.special_flash_decks where id=p_exercise::uuid;
 else
  select course_id into c from public.special_learning_catalog where kind=p_kind and exercise=p_exercise;
  if c is null or not exists(select 1 from public.special_flash_courses co where co.id=c and co.active and
   (exists(select 1 from public.special_flash_accounts a where a.id=p_account and a.role='admin' and a.active) or
    exists(select 1 from public.special_flash_enrollments e where e.account_id=p_account and e.course_id=c))) then
   raise exception 'Exercise is not available.' using errcode='42501';
  end if;
 end if;
 return c;
end $$;
revoke all on function public._special_learning_course(uuid,text,text) from public,anon,authenticated;

create function public.special_flash_activity(p_token uuid,p_events jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.special_flash_accounts:=public._special_flash_account(p_token);e jsonb;c uuid;expected jsonb;k text;item text;attempt text;ek text;pts integer;ms bigint;accepted integer:=0;changed integer;occurred timestamptz;
begin
 if a.id is null then raise exception 'Please sign in again.' using errcode='42501';end if;
 if jsonb_typeof(p_events) is distinct from 'array' or jsonb_array_length(p_events)>50 or octet_length(p_events::text)>200000 then raise exception 'Invalid event batch.' using errcode='22023';end if;
 for e in select value from jsonb_array_elements(p_events) loop
  k:=e->>'kind';item:=e->>'item';attempt:=e->>'attempt';
  if k is null or k not in ('card','blank','polysemy') or coalesce(length(item),0) not between 1 and 150 or coalesce(length(attempt),0) not between 1 and 80 or coalesce(length(e->>'exercise'),0) not between 1 and 150 then raise exception 'Invalid activity.' using errcode='22023';end if;
  c:=public._special_learning_course(a.id,k,e->>'exercise');
  pts:=0;ms:=0;
  if item like 'time:%' then
   ms:=(e->>'ms')::bigint;
   if ms is null or ms not between 1 and 60000 then raise exception 'Invalid study time.' using errcode='22023';end if;
  elsif k='card' then
   if e->>'answer' is distinct from 'green' or not exists(select 1 from public.special_flash_decks d cross join lateral jsonb_array_elements(d.cards) v where d.id=(e->>'exercise')::uuid and v->>'id'=item) then raise exception 'Invalid card.' using errcode='22023';end if;
   pts:=1;
  else
   select answers into expected from public.special_learning_catalog where kind=k and exercise=e->>'exercise';
   if k='blank' then
    if expected->>item is null or lower(replace(trim(e->>'answer'),'’','''')) is distinct from expected->>item then raise exception 'Answer is not correct.' using errcode='22023';end if;
   else
    if item<>'word' or e->'answers' is distinct from expected then raise exception 'Complete every meaning first.' using errcode='22023';end if;
   end if;
   pts:=1;
  end if;
  ek:=k||':'||(e->>'exercise')||':'||attempt||':'||item;
  occurred:=greatest(now()-interval '7 days',least(now(),coalesce(to_timestamp((e->>'at')::double precision/1000),now())));
  insert into public.special_learning_events(account_id,course_id,event_key,kind,points,duration_ms,occurred_at)
   values(a.id,c,ek,k,pts,ms,occurred) on conflict(account_id,event_key) do nothing;
  get diagnostics changed=row_count;accepted:=accepted+changed;
 end loop;
 -- Public notification contains no identities, scores, account tokens or answers.
 -- Every subscriber must still use the authenticated RPC to read its permitted data.
 if accepted>0 then
  begin perform realtime.send('{}'::jsonb,'changed','professional-learning',false);
  exception when others then null;end;
 end if;
 return jsonb_build_object('accepted',accepted);
end $$;
revoke all on function public.special_flash_activity(uuid,jsonb) from public;
grant execute on function public.special_flash_activity(uuid,jsonb) to anon,authenticated;

create function public.special_flash_learning_state(p_token uuid,p_key text default null,p_value jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.special_flash_accounts:=public._special_flash_account(p_token);result jsonb;
begin
 if a.id is null then raise exception 'Please sign in again.' using errcode='42501';end if;
 if p_key is null then
  select coalesce(jsonb_object_agg(key,value),'{}') into result from public.special_learning_state where account_id=a.id and (key like 'font:%' or key like 'bookmark:%');
  return result;
 end if;
 if length(p_key)>200 or p_key !~ '^(font:(home|flashcards|dialogue|polysemy)|draft:[a-zA-Z0-9:_-]+|bookmark:[a-zA-Z0-9:_-]+)$' then raise exception 'Invalid preference key.' using errcode='22023';end if;
 if p_value is not null then
  if octet_length(p_value::text)>100000 then raise exception 'Saved state is too large.' using errcode='22023';end if;
  if p_key like 'font:%' and p_value not in ('1'::jsonb,'2'::jsonb,'3'::jsonb,'4'::jsonb,'5'::jsonb) then raise exception 'Choose a font scale from 1 to 5.' using errcode='22023';end if;
  insert into public.special_learning_state(account_id,key,value) values(a.id,p_key,p_value)
   on conflict(account_id,key) do update set value=excluded.value,updated_at=now();
 end if;
 select value into result from public.special_learning_state where account_id=a.id and key=p_key;
 return result;
end $$;
revoke all on function public.special_flash_learning_state(uuid,text,jsonb) from public;
grant execute on function public.special_flash_learning_state(uuid,text,jsonb) to anon,authenticated;

create function public.special_flash_learning_summary(p_token uuid,p_course uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a public.special_flash_accounts:=public._special_flash_account(p_token);result jsonb;
begin
 if a.id is null then raise exception 'Please sign in again.' using errcode='42501';end if;
 if not exists(select 1 from public.special_flash_courses c where c.id=p_course and c.active and
  (a.role='admin' or exists(select 1 from public.special_flash_enrollments en where en.account_id=a.id and en.course_id=c.id))) then raise exception 'Course is not available.' using errcode='42501';end if;
 select jsonb_build_object('questions',coalesce(sum(points),0),'duration_ms',coalesce(sum(duration_ms),0),
  'cards',coalesce(sum(points) filter(where kind='card'),0),'blanks',coalesce(sum(points) filter(where kind='blank'),0),'words',coalesce(sum(points) filter(where kind='polysemy'),0),
  'daily',(select coalesce(jsonb_agg(to_jsonb(d) order by d.date),'[]') from (
   select (occurred_at at time zone 'Asia/Hong_Kong')::date as date,sum(points) as questions,sum(duration_ms) as duration_ms
   from public.special_learning_events where account_id=a.id and course_id=p_course group by 1) d)) into result
 from public.special_learning_events where account_id=a.id and course_id=p_course;
 return result;
end $$;
revoke all on function public.special_flash_learning_summary(uuid,uuid) from public;
grant execute on function public.special_flash_learning_summary(uuid,uuid) to anon,authenticated;

create or replace function public.special_flash_team_effort(p_token uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a public.special_flash_accounts:=public._special_flash_account(p_token);result jsonb;
begin
 if a.id is null then raise exception 'Please sign in again.' using errcode='42501';end if;
 with courses as (select c.* from public.special_flash_courses c where c.active and
  (a.role='admin' or exists(select 1 from public.special_flash_enrollments en where en.account_id=a.id and en.course_id=c.id))),
 members as (select c.id course_id,u.id account_id,u.username from courses c join public.special_flash_enrollments en on en.course_id=c.id join public.special_flash_accounts u on u.id=en.account_id where u.active and u.role='student'),
 totals as (select m.course_id,m.account_id,m.username,coalesce(sum(e.points),0) cards from members m left join public.special_learning_events e on e.course_id=m.course_id and e.account_id=m.account_id group by 1,2,3),
 daily as (select m.course_id,m.account_id,m.username,(e.occurred_at at time zone 'Asia/Hong_Kong')::date date,sum(e.points) cards from members m join public.special_learning_events e on e.course_id=m.course_id and e.account_id=m.account_id where e.points>0 group by 1,2,3,4)
 select jsonb_build_object('courses',coalesce(jsonb_agg(jsonb_build_object('course_id',c.id,'course_title',c.title,
  'total_cards',(select coalesce(sum(t.cards),0) from totals t where t.course_id=c.id),
  'members',(select coalesce(jsonb_agg(jsonb_build_object('account_id',t.account_id,'username',t.username,'cards',t.cards) order by t.cards desc,t.username),'[]') from totals t where t.course_id=c.id),
  'daily',(select coalesce(jsonb_agg(jsonb_build_object('date',d.date,'account_id',d.account_id,'username',d.username,'cards',d.cards) order by d.date,d.username),'[]') from daily d where d.course_id=c.id)) order by c.title),'[]')) into result from courses c;
 return result;
end $$;

